list.query:
WITH options AS (
  SELECT snapshot_id, coalesce(last_received_at, window_end) AS latest
  FROM analytics.scopes WHERE namespace_id = ${namespace:sqlstring}
)
SELECT __text, __value FROM (
  SELECT snapshot_id AS __text, snapshot_id AS __value, latest FROM options
  UNION ALL
  SELECT '— потоков и срезов нет —', '', NULL WHERE NOT EXISTS (SELECT 1 FROM options)
) AS listed
ORDER BY latest DESC NULLS LAST

